  ADVICE_END: "どれも「できそうなところから一つだけ」で大丈夫です。",
  /** アドバイス部品の優先順位（代表特徴の並びに対する添字）：運命線→生命線→感情線→頭脳線 */
  ADVICE_PRIORITY: [3, 0, 2, 1],

  /**
   * アドバイス文の合成（決定的）。
   * 中間の段階（レベル1）でない線を優先して最大2文を選び、締めの文を付ける。
   * すべて中間の段階だった場合は、運命線と生命線の部品を使う。
   */
  adviceText: function(arc, slope, reach, unmeiDark) {
    var levels = [arc, slope, reach, unmeiDark];
    var sb = "";
    var picked = 0;
    for (var pi = 0; pi < Tesou.ADVICE_PRIORITY.length && picked < 2; pi++) {
      var rep = Tesou.ADVICE_PRIORITY[pi];
      if (levels[rep] !== 1) {
        sb += Tesou.ADVICE_PHRASE[rep][levels[rep]];
        picked++;
      }
    }
    if (picked === 0) {
      sb += Tesou.ADVICE_PHRASE[3][levels[3]];
      sb += Tesou.ADVICE_PHRASE[0][levels[0]];
    }
    sb += Tesou.ADVICE_END;
    return sb;
  }
